import json
def q(w,r,ro,m,p,e,er,eo,tr,u,n):return {'word':w,'reading':r,'romaji':ro,'meaning':m,'pos':p,'usage':u,'example':e,'example_reading':er,'example_romaji':eo,'translation':tr,'nuance':n}
raw=[
('天気','てんき','tenki','weather','noun','天気が急に変わった。','てんきがきゅうにかわった。','Tenki ga kyuu ni kawatta.','The weather changed suddenly.','天気が変わる','天気 is everyday weather on a particular day.'),('気候','きこう','kou','climate','noun','この地域は温暖な気候です。','このちいきはおんだんなきこうです。','Kono chiiki wa ondan na kikou desu.','This region has a mild climate.','温暖な気候','気候 describes long-term regional patterns.'),('予報','よほう','yohou','forecast','noun','明日の予報では雨です。','あしたのよほうではあめです。','Ashita no yohou de wa ame desu.','Tomorrow’s forecast says rain.','天気予報','予報 is a prediction, especially a weather forecast.'),('晴れ','はれ','hare','clear weather','noun','晴れの日は洗濯物がよく乾く。','はれのひはせんたくものがよくかわく。','Hare no hi wa sentakumono ga yoku kawaku.','Laundry dries well on clear days.','晴れの日','晴れ means clear or sunny weather.'),('曇り','くもり','kumori','cloudy weather','noun','午後は曇りになるでしょう。','ごごはくもりになるでしょう。','Gogo wa kumori ni naru deshou.','It will probably become cloudy in the afternoon.','曇りになる','曇り is cloudy weather, without necessarily meaning rain.'),('雨量','うりょう','uryou','rainfall','noun','今年は雨量が少ない。','ことしはうりょうがすくない。','Kotoshi wa uryou ga sukunai.','Rainfall is low this year.','雨量が多い','雨量 is the measured amount of rain.'),('大雨','おおあめ','ooame','heavy rain','noun','大雨で川の水位が上がった。','おおあめでかわのすいいがあがった。','Ooame de kawa no suii ga agatta.','The river level rose because of heavy rain.','大雨が降る','大雨 means unusually heavy rain and may signal danger.'),('雪','ゆき','yuki','snow','noun','夜の間に雪が積もった。','よるのあいだにゆきがつもった。','Yoru no aida ni yuki ga tsumotta.','Snow accumulated overnight.','雪が積もる','雪 means snow; 積もる describes accumulation.'),('吹雪','ふぶき','fubuki','blizzard','noun','吹雪で道路が通行止めになった。','ふぶきでどうろがつうこうどめになった。','Fubuki de douro ga tsuukoudome ni natta.','The road was closed because of a blizzard.','吹雪になる','吹雪 is a severe snowstorm with strong wind.'),('雷','かみなり','kaminari','thunder','noun','雷が鳴ったので窓を閉めた。','かみなりがなったのでまどをしめた。','Kaminari ga natta node mado o shimeta.','I closed the window because thunder sounded.','雷が鳴る','雷 refers to thunder and is also used for lightning in everyday speech.'),('風速','ふうそく','fuusoku','wind speed','noun','風速が毎秒二十メートルに達した。','ふうそくがまいびょうにじゅうめーとるにたっした。','Fuusoku ga maibyou nijuumeetoru ni tasshita.','Wind speed reached twenty meters per second.','最大風速','風速 is wind speed, measured in units such as m/s.'),('湿度','しつど','shitsudo','humidity','noun','今日は湿度が高くて蒸し暑い。','きょうはしつどがたかくてむしあつい。','Kyou wa shitsudo ga takakute mushiatsui.','It is hot and muggy because humidity is high today.','湿度が高い','湿度 is the amount of moisture in the air.'),('気温','きおん','kion','air temperature','noun','朝の気温は五度でした。','あさのきおんはごどでした。','Asa no kion wa go do deshita.','The morning air temperature was five degrees.','気温が下がる','気温 specifically means atmospheric temperature.'),('温度','おんど','ondo','temperature','noun','冷蔵庫の温度を確認した。','れいぞうこのおんどをかくにんした。','Reizouko no ondo o kakunin shita.','I checked the refrigerator temperature.','温度を測る','温度 is general temperature of an object or space.'),('季節','きせつ','kisetsu','season','noun','季節の変わり目は体調を崩しやすい。','きせつのかわりめはたいちょうをくずしやすい。','Kisetsu no kawarime wa taichou o kuzushi yasui.','It is easy to get sick when the seasons change.','季節の変わり目','季節 means one of the four seasons or a season of life.'),('梅雨','つゆ','tsuyu','rainy season','noun','梅雨は六月ごろに始まる。','つゆはろくがつごろにはじまる。','Tsuyu wa rokugatsu goro ni hajimaru.','Japan’s rainy season begins around June.','梅雨が明ける','梅雨 is Japan’s early-summer rainy season.'),('台風','たいふう','taifuu','typhoon','noun','台風が近づいたため休校になった。','たいふうがちかづいたためきゅうこうになった。','Taifuu ga chikazuita tame kyuukou ni natta.','School was closed because a typhoon approached.','台風が接近する','台風 is a tropical cyclone affecting Japan and nearby regions.'),('災害','さいがい','saigai','disaster','noun','災害に備えて水を保存する。','さいがいにそなえてみずをほぞんする。','Saigai ni sonaete mizu o hozon suru.','We store water in preparation for disasters.','災害に備える','災害 is a disaster such as an earthquake, flood, or storm.'),('洪水','こうずい','kouzui','flood','noun','川があふれて洪水になった。','かわがあふれてこうずいになった。','Kawa ga afurete kouzui ni natta.','The river overflowed and caused a flood.','洪水が起きる','洪水 is flooding caused by overflowing water.'),('土砂崩れ','どしゃくずれ','dosha kuzure','landslide','noun','大雨で土砂崩れが発生した。','おおあめでどしゃくずれがはっせいした。','Ooame de dosha kuzure ga hassei shita.','A landslide occurred because of heavy rain.','土砂崩れが発生する','土砂崩れ is a landslide of earth and rocks.'),('停電','ていでん','teiden','power outage','noun/suru verb','台風で町が停電した。','たいふうでまちがていでんした。','Taifuu de machi ga teiden shita.','The town lost power because of the typhoon.','停電する','停電 means an interruption of electrical power.'),('節電','せつでん','setsuden','power saving','noun/suru verb','夏は冷房の設定を変えて節電する。','なつはれいぼうのせっていをかえてせつでんする。','Natsu wa reibou no settei o kaete setsuden suru.','In summer, we save power by changing the air-conditioning setting.','節電する','節電 means reducing electricity use.'),('資源','しげん','shigen','resource','noun','限りある資源を大切に使おう。','かぎりあるしげんをたいせつにつかおう。','Kagiri aru shigen o taisetsu ni tsukaou.','Let’s use our limited resources carefully.','資源を守る','資源 includes natural resources and recyclable materials.'),('ごみ','ごみ','gomi','garbage','noun','ごみを決められた日に出す。','ごみをきめられたひにだす。','Gomi o kimerareta hi ni dasu.','I put out the garbage on the designated day.','ごみを出す','ごみ is everyday garbage or waste.'),('分別','ぶんべつ','bunbetsu','sorting; separation','noun/suru verb','地域の規則に従ってごみを分別する。','ちいきのきそくにしたがってごみをぶんべつする。','Chiiki no kisoku ni shitagatte gomi o bunbetsu suru.','We sort garbage according to local rules.','ごみを分別する','分別 means separating items into categories, especially waste.'),('再利用','さいりよう','sairiyou','reuse','noun/suru verb','空き瓶を再利用して花を飾った。','あきびんをさいりようしてはなをかざった。','Akibin o sairiyou shite hana o kazatta.','I reused an empty bottle to display flowers.','資源を再利用する','再利用 means use something again rather than discard it.'),('排気ガス','はいきがす','haiki gasu','exhaust gas','noun','車の排気ガスが空気を汚す。','くるまのはいきがすがくうきをよごす。','Kuruma no haiki gasu ga kuuki o yogosu.','Car exhaust pollutes the air.','排気ガスを減らす','排気ガス is gas emitted by engines.'),('温暖化','おんだんか','ondanka','global warming','noun/suru verb','温暖化で海面が上昇している。','おんだんかでかいめんがじょうしょうしている。','Ondanka de kaimen ga joushou shite iru.','Sea levels are rising because of global warming.','地球温暖化','温暖化 means warming, especially the earth’s climate.'),('汚染','おせん','osen','pollution; contamination','noun/suru verb','工場が川の水を汚染した。','こうじょうがかわのみずをおせんした。','Koujou ga kawa no mizu o osen shita.','The factory polluted the river water.','大気汚染','汚染 means harmful contamination of air, water, or land.'),('省エネ','しょうえね','shouene','energy saving','noun','省エネの家電に買い替えた。','しょうえねのかでんにかいかえた。','Shouene no kaden ni kaikaeta.','I replaced my appliance with an energy-saving model.','省エネ家電','省エネ is a common abbreviation for energy conservation.')]
items=[q(*x) for x in raw]
ex=[{'type':'meaning','question':'What does 吹雪 mean?','options':['blizzard','humidity','climate','flood'],'answer':'blizzard','explanation':'吹雪 means blizzard.'},{'type':'reading','question':'Choose the reading for 土砂崩れ.','options':['どしゃくずれ','どさくずれ','つちくずれ','どしゃほうれ'],'answer':'どしゃくずれ','explanation':'土砂崩れ is read どしゃくずれ.'},{'type':'collocation','question':'Which phrase means “sort garbage”?','options':['ごみを分別する','雨量を測る','台風が鳴る','資源を降る'],'answer':'ごみを分別する','explanation':'ごみを分別する is the natural phrase.'},{'type':'translation','question':'Translate: 台風が近づいたため休校になった。','answer':'School was closed because a typhoon approached.','explanation':'台風 means typhoon.'},{'type':'particle','question':'Choose: 災害＿＿備える。','options':['に','を','が','で'],'answer':'に','explanation':'The fixed pattern is 災害に備える.'},{'type':'contrast','question':'Which word means energy saving?','options':['省エネ','温暖化','汚染','排気ガス'],'answer':'省エネ','explanation':'省エネ means energy conservation.'}]
json.dump({'id':20,'title':'Weather and environment','overview':'Vocabulary for weather conditions, disasters, environmental problems, and conservation.','items':items,'exercises':ex},open('content/vocab_20.json','w',encoding='utf8'),ensure_ascii=False,indent=2)
